# 自动化红队循环(示意)
for batch in attack_generator(seeds, target_system):
    for attack in batch:
        response = executor.run(attack)          # 隔离环境执行
        verdict = judge(response, attack.goal)   # 成功判定
        if verdict.success:
            regression.add(attack)               # 回归固化
            report.add(attack, response)         # 漏洞报告
        else:
            analyzer.learn(attack, response)     # 防线特征学习
# 生成器基于 analyzer 的反馈进化新变体
```

